#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    string removeKBalancedSubstrings(string s, int k) {
        vector<pair<char, int>> stack;
        for (char c : s) {
            if (!stack.empty() && stack.back().first == c) {
                stack.back().second++;
            } else {
                stack.push_back({c, 1});
            }
            if (stack.size() >= 2 && stack[stack.size() - 2].first == '0' && stack.back().first == '1') {
                if (stack[stack.size() - 2].second >= k && stack.back().second >= k) {
                    stack[stack.size() - 2].second -= k;
                    stack.back().second -= k;
                    if (stack.back().second == 0) stack.pop_back();
                    if (!stack.empty() && stack.back().second == 0) stack.pop_back();
                    if (stack.size() >= 2 && stack.back().first == stack[stack.size() - 2].first) {
                        stack[stack.size() - 2].second += stack.back().second;
                        stack.pop_back();
                    }
                }
            }
        }
        string res = "";
        for (auto& p : stack) {
            res.append(p.second, p.first);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String removeKBalancedSubstrings(String s, int k) {
        List<int[]> stack = new ArrayList<>(); // [char_code, count]
        for (char c : s.toCharArray()) {
            if (!stack.isEmpty() && stack.get(stack.size() - 1)[0] == c) {
                stack.get(stack.size() - 1)[1]++;
            } else {
                stack.add(new int[]{c, 1});
            }
            int sz = stack.size();
            if (sz >= 2 && stack.get(sz - 2)[0] == '0' && stack.get(sz - 1)[0] == '1') {
                if (stack.get(sz - 2)[1] >= k && stack.get(sz - 1)[1] >= k) {
                    stack.get(sz - 2)[1] -= k;
                    stack.get(sz - 1)[1] -= k;
                    if (stack.get(sz - 1)[1] == 0) stack.remove(sz - 1);
                    if (!stack.isEmpty() && stack.get(stack.size() - 1)[1] == 0) {
                        stack.remove(stack.size() - 1);
                    }
                    sz = stack.size();
                    if (sz >= 2 && stack.get(sz - 1)[0] == stack.get(sz - 2)[0]) {
                        stack.get(sz - 2)[1] += stack.get(sz - 1)[1];
                        stack.remove(sz - 1);
                    }
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int[] p : stack) {
            for (int i = 0; i < p[1]; i++) sb.append((char)p[0]);
        }
        return sb.toString();
    }
}

var removeKBalancedSubstrings = function(s, k) {
    const stack = [];
    for (const c of s) {
        if (stack.length > 0 && stack[stack.length - 1][0] === c) {
            stack[stack.length - 1][1]++;
        } else {
            stack.push([c, 1]);
        }
        let sz = stack.length;
        if (sz >= 2 && stack[sz - 2][0] === '0' && stack[sz - 1][0] === '1') {
            if (stack[sz - 2][1] >= k && stack[sz - 1][1] >= k) {
                stack[sz - 2][1] -= k;
                stack[sz - 1][1] -= k;
                if (stack[sz - 1][1] === 0) stack.pop();
                if (stack.length > 0 && stack[stack.length - 1][1] === 0) stack.pop();
                sz = stack.length;
                if (sz >= 2 && stack[sz - 1][0] === stack[sz - 2][0]) {
                    stack[sz - 2][1] += stack[sz - 1][1];
                    stack.pop();
                }
            }
        }
    }
    let res = "";
    for (const [ch, cnt] of stack) {
        res += ch.repeat(cnt);
    }
    return res;
};
